def chuoi_vuot(xs, nguong, k):
    kq, dem = [], 0
    for i, x in enumerate(xs):
        if x > nguong:
            dem += 1
            if dem == k:
                kq.append(i - k + 1)
        else:
            dem = 0
    return kq

def canh_bao(do, nguong):
    tb = (do.sort_values("ts")
            .groupby("may")
            .tail(3)
            .groupby("may")["nhiet"].mean())
    return sorted(tb[tb > nguong].index.tolist())
